 <section class="overlay" id="intro"><div class="intro"><div class="kicker">A CINEMATIC ARENA BRAWLER</div><h1>ONE TEAM.<span>ONE RIFT.</span></h1><p>Lead the Vanguard into a living battlefield. Rally your allied champions, break the Legion's defenses, and bring down their Nexus before they reach yours.</p><button class="start" id="start">ENTER THE RIFT&nbsp; →</button><div class="controls"><span><i class="key">W</i><i class="key">A</i><i class="key">S</i><i class="key">D</i> Move</span><span><i class="key">Q</i><i class="key">W</i><i class="key">E</i><i class="key">R</i> Abilities</span><span><i class="key">SPACE</i> Attack nearest</span></div></div></section>
 <section class="result hidden" id="result"><div class="resultbox"><div class="eyebrow">BATTLE REPORT</div><h2 id="resulttitle">VICTORY</h2><p id="resultcopy">The Nexus is secure. The Rift remembers.</p><button class="start" id="again">FIGHT AGAIN&nbsp; →</button></div></section>
 </main>
 <script>
+const canvas=document.querySelector('#arena'),ctx=canvas.getContext('2d');
+const W=1280,H=720;let cw=0,ch=0,scaleX=1,scaleY=1;
+function resize(){const d=Math.min(devicePixelRatio||1,2);cw=canvas.width=Math.floor(innerWidth*d);ch=canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';scaleX=cw/W;scaleY=ch/H;ctx.setTransform(scaleX,0,0,scaleY,0,0)}addEventListener('resize',resize);resize();
+const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+let started=false,ended=false,elapsed=0,last=0,spawnTimer=1,toastTimer=0;
+const player={x:355,y:594,r:19,hp:100,max:100,mana:100,maxMana:100,attack:0,level:1,xp:0,kills:0,face:0};
+let allies=[],foes=[],shots=[],particles=[],floaters=[],skills={q:0,w:0,e:0,r:0},towers=[{x:510,y:495,team:0,hp:320,max:320},{x:795,y:317,team:1,hp:320,max:320}],cores=[{x:205,y:665,team:0,hp:800,max:800},{x:1085,y:151,team:1,hp:800,max:800}];
+let pointer={x:650,y:350},keys={},kills=0,alliedScore=0,enemyScore=0;
+function announce(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.2}
+function spawnWave(){for(let i=0;i<3;i++){const offset=(i-1)*15;allies.push({x:365+offset,y:580-offset,r:10,hp:48,max:48,team:0,kind:'minion',speed:22,attack:0,phase:rand(0,6)});foes.push({x:915+offset,y:245-offset,r:10,hp:48,max:48,team:1,kind:'minion',speed:21,attack:0,phase:rand(0,6)})}allies.push({x:349,y:599,r:14,hp:120,max:120,team:0,kind:'champ',speed:17,attack:0,phase:rand(0,6)});foes.push({x:936,y:221,r:14,hp:125,max:125,team:1,kind:'champ',speed:16,attack:0,phase:rand(0,6)})}
+function lanePoint(t){return{x:330+(1010-330)*t,y:647+(95-647)*t}}
+function drawMap(t){
+ ctx.fillStyle='#15382e';ctx.fillRect(0,0,W,H);
+ // forest canopy mosaics
+ for(let y=-20;y<H+30;y+=49)for(let x=-15;x<W+30;x+=53){let v=Math.sin(x*12.3+y*3.1)*.5+.5;ctx.fillStyle=v>.48?'#1a4033':'#183a31';ctx.beginPath();ctx.arc(x+((y/49|0)%2)*24,y,rand(18,28),0,Math.PI*2);ctx.fill();ctx.fillStyle='#244938';ctx.beginPath();ctx.arc(x-7,y-8,rand(5,11),0,Math.PI*2);ctx.fill()}
+ // dark path edges + lane
+ ctx.lineCap='round';ctx.beginPath();ctx.moveTo(260,700);ctx.lineTo(1040,52);ctx.strokeStyle='#253c35';ctx.lineWidth=205;ctx.stroke();ctx.beginPath();ctx.moveTo(260,700);ctx.lineTo(1040,52);ctx.strokeStyle='#78694c';ctx.lineWidth=155;ctx.stroke();ctx.beginPath();ctx.moveTo(260,700);ctx.lineTo(1040,52);ctx.strokeStyle='#8c7953';ctx.lineWidth=139;ctx.stroke();
+ // paving stone seams
+ for(let i=0;i<25;i++){let p=lanePoint(i/24);ctx.strokeStyle=i%2?'#aa9668':'#655d48';ctx.globalAlpha=.35;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-70,p.y-48);ctx.lineTo(p.x+70,p.y+48);ctx.stroke()}ctx.globalAlpha=1;
+ // jungle monuments and pools
+ for(const [x,y,c] of [[455,266,'#55d8dc'],[855,549,'#ed7958'],[713,168,'#64d6cb'],[574,477,'#52d4c8'],[287,422,'#e89057'],[997,440,'#da725c']]){ctx.fillStyle='#0c201e';ctx.beginPath();ctx.ellipse(x,y,36,22,-.6,0,7);ctx.fill();ctx.strokeStyle='#386a5b';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle=c;ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x,y,4+Math.sin(t*2+x)*1.5,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#86c5a1';ctx.globalAlpha=.4;ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,13+Math.sin(t+x)*2,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
+ // ornamental trees, roots
+ for(let i=0;i<30;i++){const x=((i*173+87)%1240)+20,y=((i*293+55)%670)+25;if((x>260&&x<1040&&Math.abs((y-(700-(x-260)*.83)))<90))continue;ctx.fillStyle='#112b26';ctx.beginPath();ctx.ellipse(x,y,18,11,.3,0,7);ctx.fill();ctx.fillStyle=i%3?'#28513d':'#31543e';ctx.beginPath();ctx.arc(x,y,11+(i%3)*2,0,7);ctx.fill();ctx.fillStyle='#5e7949';ctx.globalAlpha=.45;ctx.beginPath();ctx.arc(x-3,y-4,5,0,7);ctx.fill();ctx.globalAlpha=1}
+ // base nexus glows
+ drawCore(cores[0],t);drawCore(cores[1],t);towers.forEach(drawTower);
+}
+function drawCore(o,t){const blue=o.team===0;ctx.save();ctx.translate(o.x,o.y);ctx.fillStyle='#071313';ctx.beginPath();ctx.ellipse(0,8,47,24,0,0,7);ctx.fill();ctx.strokeStyle=blue?'#6de9ef':'#ff796a';ctx.lineWidth=2;ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(0,-5,32+Math.sin(t*2)*2,0,7);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#334a48';ctx.beginPath();ctx.moveTo(-25,7);ctx.lineTo(-18,-28);ctx.lineTo(0,-42);ctx.lineTo(18,-28);ctx.lineTo(25,7);ctx.closePath();ctx.fill();let g=ctx.createRadialGradient(0,-20,2,0,-20,21);g.addColorStop(0,blue?'#f7ffff':'#fff0cf');g.addColorStop(.3,blue?'#6df5ff':'#ff725d');g.addColorStop(1,blue?'#18798e':'#8c2c39');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,-40);ctx.lineTo(16,-20);ctx.lineTo(0,1);ctx.lineTo(-16,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#d7bd77';ctx.fillRect(-28,9,56,4);ctx.restore();bar(o.x-31,o.y-51,62,5,o.hp/o.max,blue?'#71e6ed':'#ff796a')}
+function drawTower(o){const blue=o.team===0;ctx.save();ctx.translate(o.x,o.y);ctx.fillStyle='#06141366';ctx.beginPath();ctx.ellipse(0,8,36,19,0,0,7);ctx.fill();ctx.fillStyle='#5a604d';ctx.beginPath();ctx.moveTo(-23,4);ctx.lineTo(-18,-22);ctx.lineTo(0,-39);ctx.lineTo(18,-22);ctx.lineTo(23,4);ctx.closePath();ctx.fill();ctx.strokeStyle=blue?'#72e9ee':'#ff7b68';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=blue?'#49dce8':'#f27863';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=15;ctx.beginPath();ctx.arc(0,-22,7+Math.sin(elapsed*3)*1,0,7);ctx.fill();ctx.shadowBlur=0;ctx.restore();bar(o.x-26,o.y-48,52,4,o.hp/o.max,blue?'#69e7ee':'#ff7869')}
+function bar(x,y,w,h,p,color){ctx.fillStyle='#101719';ctx.fillRect(x-1,y-1,w+2,h+2);ctx.fillStyle='#3d2927';ctx.fillRect(x,y,w,h);ctx.fillStyle=color;ctx.fillRect(x,y,w*clamp(p,0,1),h)}

