function bar(x,y,w,h,p,color){ctx.fillStyle='#101719';ctx.fillRect(x-1,y-1,w+2,h+2);ctx.fillStyle='#3d2927';ctx.fillRect(x,y,w,h);ctx.fillStyle=color;ctx.fillRect(x,y,w*clamp(p,0,1),h)}
function drawUnit(u,t){if(u.hp<=0)return;const blue=u.team===0;ctx.save();ctx.translate(u.x,u.y+Math.sin(t*4+u.phase)*1.1);ctx.fillStyle='#02090888';ctx.beginPath();ctx.ellipse(0,7,u.r*1.25,u.r*.63,0,0,7);ctx.fill();if(u.kind==='champ'){ctx.strokeStyle=blue?'#6de7ef':'#ff7768';ctx.lineWidth=2;ctx.globalAlpha=.55;ctx.beginPath();ctx.arc(0,0,u.r+5,0,7);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#34494c';ctx.beginPath();ctx.moveTo(-14,7);ctx.lineTo(-12,-7);ctx.lineTo(-7,-16);ctx.lineTo(0,-20);ctx.lineTo(10,-15);ctx.lineTo(14,3);ctx.lineTo(8,12);ctx.lineTo(-9,12);ctx.closePath();ctx.fill();ctx.strokeStyle=blue?'#71edf1':'#ff8670';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=blue?'#c5fbf4':'#ffd4c3';ctx.beginPath();ctx.ellipse(0,-12,7,8,0,0,7);ctx.fill();ctx.fillStyle=blue?'#56d8e6':'#f27867';ctx.beginPath();ctx.moveTo(-7,-14);ctx.lineTo(-3,-25);ctx.lineTo(1,-16);ctx.lineTo(7,-24);ctx.lineTo(7,-12);ctx.closePath();ctx.fill();ctx.fillStyle='#efe2bd';ctx.fillRect(10,-2,3,14);ctx.strokeStyle='#e3cb83';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(11,3);ctx.lineTo(19,-8);ctx.stroke()}else{ctx.fillStyle=blue?'#287c7e':'#89463f';ctx.beginPath();ctx.arc(0,0,u.r,0,7);ctx.fill();ctx.strokeStyle=blue?'#92e8d8':'#e69a72';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#d5cc9d';ctx.fillRect(-3,-u.r-5,6,9);ctx.fillStyle=blue?'#8cf0ed':'#ff907a';ctx.beginPath();ctx.arc(0,-2,3,0,7);ctx.fill()}ctx.restore();if(u.hp<u.max)bar(u.x-u.r,u.y-u.r-9,u.r*2,3,u.hp/u.max,blue?'#6de8dc':'#ff7568')}
function drawPlayer(t){drawUnit({...player,team:0,kind:'champ',r:player.r,hp:player.hp,max:player.max,phase:0},t);ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.face);ctx.strokeStyle='#f6d279';ctx.lineWidth=2;ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(28,0);ctx.stroke();ctx.globalAlpha=1;ctx.restore();}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(35,180);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.25,.8),max:.8,color,r:rand(2,5)})}}
function shot(x,y,target,team,damage,color,speed=400){const dx=target.x-x,dy=target.y-y,d=Math.hypot(dx,dy)||1;shots.push({x,y,vx:dx/d*speed,vy:dy/d*speed,life:d/speed+.1,team,damage,color,target})}
function closestTarget(x,y,enemyOnly=true){const candidates=[...foes.filter(x=>x.hp>0),...towers.filter(t=>t.team===1&&t.hp>0),...(cores[1].hp>0&&towers.filter(t=>t.team===1).every(t=>t.hp<=0)?[cores[1]]:[])];let best=null,bd=Infinity;for(const e of candidates){const d=Math.hypot(e.x-x,e.y-y);if(d<bd){bd=d;best=e}}return best?{target:best,d:bd}:null}
function damageTarget(target,amount,color='#ffcf73'){if(!target||target.hp<=0)return;target.hp-=amount;floaters.push({x:target.x,y:target.y-20,text:`-${Math.round(amount)}`,life:.7,color});burst(target.x,target.y,color,5);if(target.hp<=0){target.hp=0;if(foes.includes(target)){foes=foes.filter(e=>e!==target);if(target.kind==='champ'){enemyScore++;document.querySelector('.side.red').textContent=enemyScore;announce('RIVAL CHAMPION DOWN');}else alliedScore++;player.xp+=target.kind==='champ'?35:12;gainXp()}else if(towers.includes(target)){announce('ENEMY TOWER DESTROYED');player.xp+=80;gainXp()}else if(target===cores[1])finish(true);else if(target===cores[0])finish(false)}}
function gainXp(){if(player.xp>=player.level*65){player.xp=0;player.level++;player.max+=15;player.hp=Math.min(player.max,player.hp+30);player.maxMana+=10;announce(`LEVEL UP · ${player.level}`);document.querySelector('#level').textContent=player.level}}
function useSkill(k){if(!started||ended||skills[k]>0)return;const costs={q:20,w:25,e:15,r:50};if(player.mana<costs[k]){announce('NOT ENOUGH MANA');return}player.mana-=costs[k];const aim={x:pointer.x,y:pointer.y};if(k==='q'){const target=closestTarget(player.x,player.y);if(target&&target.d<520){shot(player.x,player.y-8,target.target,0,48+player.level*5,'#8df9ff',590);skills.q=4;announce('STAR LANCE')}else{skills.q=4;burst(player.x+Math.cos(player.face)*18,player.y+Math.sin(player.face)*18,'#8df9ff',15)}}if(k==='w'){skills.w=9;player.hp=Math.min(player.max,player.hp+22);burst(player.x,player.y,'#76eddf',28);for(const f of foes.filter(f=>Math.hypot(f.x-player.x,f.y-player.y)<115))damageTarget(f,36+player.level*4,'#83fff2');announce('AEGIS PULSE')}if(k==='e'){skills.e=7;let dx=aim.x-player.x,dy=aim.y-player.y,d=Math.hypot(dx,dy);if(d<10){dx=Math.cos(player.face);dy=Math.sin(player.face);d=1}player.x=clamp(player.x+dx/d*115,80,1200);player.y=clamp(player.y+dy/d*115,45,685);player.face=Math.atan2(dy,dx);burst(player.x,player.y,'#d7baff',18);for(const f of foes.filter(f=>Math.hypot(f.x-player.x,f.y-player.y)<65))damageTarget(f,25,'#d7baff');announce('COMET STRIDE')}if(k==='r'){skills.r=24;const x=aim.x,y=aim.y;burst(x,y,'#ffe28a',48);for(const f of foes.filter(f=>Math.hypot(f.x-x,f.y-y)<155))damageTarget(f,105+player.level*12,'#ffe28a');for(const t of towers.filter(t=>t.team===1&&Math.hypot(t.x-x,t.y-y)<120))damageTarget(t,80,'#ffe28a');announce('SUPERNOVA · UNLEASHED')}}

